 "content": "def transform(grid):
    """Stamp the seed color's pixel shape wherever it fits entirely on zeros."""
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v not in (0, 9)}
    if len(colors) != 1:
        return [row[:] for row in grid]
    color = next(iter(colors))
    pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
    # Seed pixels form one 8-connected object; take its pixel mask.
    start = next(iter(pts))
    comp, stack = {start}, [start]
    while stack:
        r, c = stack.pop()
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                q = (r + dr, c + dc)
                if q in pts and q not in comp:
                    comp.add(q)
                    stack.append(q)
    r0 = min(r for r, c in comp)
    c0 = min(c for r, c in comp)
    mask = {(r-r0, c-c0) for r, c in comp}
    mh = max(r for r, c in mask) + 1
    mw = max(c for r, c in mask) + 1
    out = [row[:] for row in grid]
    for r in range(h - mh + 1):
        for c in range(w - mw + 1):
            if all(grid[r+dr][c+dc] == 0 for dr, dc in mask):
                for dr, dc in mask:
                    out[r+dr][c+dc] = color
    return out
